 public sealed partial class GroupChatForm:Form
 {
  readonly IDataService db=DataService.Instance; readonly ChatGroup group; readonly RealtimeSettings realtimeSettings=new RealtimeSettings(); readonly IRealtimeClient realtime; Action<string,string,string> groupMessageHandler;
  readonly FlowLayoutPanel history=new FlowLayoutPanel(); readonly TextBox input=new TextBox();
  readonly Label title=new Label(); readonly Label replyPreview=new Label(); string replyId;
  public GroupChatForm(ChatGroup g){InitializeComponent();group=g;realtime=RealtimeClientFactory.Create(realtimeSettings);Text=g.Name;StartPosition=FormStartPosition.CenterParent;Size=new Size(900,680);MinimumSize=new Size(760,560);BackColor=ThemeColors.Background;BackgroundService.Apply(this,"Group Chat");Build();Render();Shown+=async (s,e)=>{try{await realtime.ConnectAsync(Session.CurrentUser.Id);await realtime.JoinGroupAsync(group.Id);}catch(Exception ex){AppLogger.Error("Group realtime connection failed.",ex);}};groupMessageHandler=(gid,from,text)=>{if(gid!=group.Id||from==Session.CurrentUser.Id)return;BeginInvoke((Action)(()=>{db.Data.GroupMessages.Add(new GroupChatMessage{Id=Guid.NewGuid().ToString(),GroupId=gid,FromUserId=from,Text=text,CreatedAt=DateTime.Now});db.Save();Render();}));};realtime.GroupMessageReceived+=groupMessageHandler;FormClosed+=(s,e)=>{try{realtime.GroupMessageReceived-=groupMessageHandler;realtime.Dispose();}catch{}};}
  void Build(){
   var header=new Panel{Dock=DockStyle.Top,Height=72,BackColor=ThemeColors.Surface,Padding=new Padding(18,10,18,8)};
   title.Text=group.Name;title.Location=new Point(18,9);title.Size=new Size(430,25);title.ForeColor=ThemeColors.TextPrimary;title.Font=new Font("Segoe UI Semibold",12,FontStyle.Bold);header.Controls.Add(title);
   var sub=new Label{Text=group.MemberUserIds.Count+" members  ·  realtime ready",Location=new Point(18,39),AutoSize=true,ForeColor=ThemeColors.TextMuted};header.Controls.Add(sub);
   var search=ButtonX("Search",Width-470,16,100);search.Anchor=AnchorStyles.Top|AnchorStyles.Right;search.Click+=(s,e)=>SearchMessages();header.Controls.Add(search);var info=ButtonX("Group info",Width-360,16,100);info.Anchor=AnchorStyles.Top|AnchorStyles.Right;info.Click+=(s,e)=>ShowInfo();header.Controls.Add(info);
   var manage=ButtonX("Manage",Width-250,16,100);manage.Anchor=AnchorStyles.Top|AnchorStyles.Right;manage.Click+=(s,e)=>ManageGroup();header.Controls.Add(manage);
   var add=ButtonX("Add member",Width-140,16,105);add.Anchor=AnchorStyles.Top|AnchorStyles.Right;add.Click+=(s,e)=>AddMember();header.Controls.Add(add);Controls.Add(header);
   history.Dock=DockStyle.Fill;history.AutoScroll=true;history.FlowDirection=FlowDirection.TopDown;history.WrapContents=false;history.Padding=new Padding(24,18,24,18);history.BackColor=ThemeColors.Background;Controls.Add(history);
   var composer=new Panel{Dock=DockStyle.Bottom,Height=96,BackColor=ThemeColors.Surface,Padding=new Padding(12)};
   replyPreview.Location=new Point(62,5);replyPreview.Size=new Size(Width-230,22);replyPreview.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Top;replyPreview.ForeColor=ThemeColors.Primary;replyPreview.Font=new Font("Segoe UI",8);replyPreview.Visible=false;composer.Controls.Add(replyPreview);
   var attach=ButtonX("+",10,40,42);attach.Click+=(s,e)=>Attach();composer.Controls.Add(attach);var emoji=ButtonX("☺",58,40,42);emoji.Click+=(s,e)=>ShowEmoji(emoji);composer.Controls.Add(emoji);
   input.Location=new Point(106,42);input.Size=new Size(Width-234,36);input.Anchor=AnchorStyles.Left|AnchorStyles.Right|AnchorStyles.Bottom;input.Font=new Font("Segoe UI",10);input.BackColor=ThemeColors.SurfaceHover;input.ForeColor=ThemeColors.TextPrimary;input.BorderStyle=BorderStyle.FixedSingle;composer.Controls.Add(input);
   var send=ButtonX("Send",Width-112,39,78);send.Anchor=AnchorStyles.Right|AnchorStyles.Bottom;send.Click+=(s,e)=>Send();composer.Controls.Add(send);input.KeyDown+=(s,e)=>{if(e.KeyCode==Keys.Enter){Send();e.SuppressKeyPress=true;}};Controls.Add(composer);composer.BringToFront();
  }
  ModernButton ButtonX(string t,int x,int y,int w){return new ModernButton{Text=t,Location=new Point(x,y),Size=new Size(w,40),BackColor=ThemeColors.Primary,ForeColor=Color.White,BorderRadius=18};}
  void Render(){history.Controls.Clear();foreach(var m in db.Data.GroupMessages.Where(x=>x.GroupId==group.Id).OrderBy(x=>x.CreatedAt)){var u=db.Data.Users.FirstOrDefault(x=>x.Id==m.FromUserId);bool mine=m.FromUserId==Session.CurrentUser.Id;int textLines=Math.Max(1,(m.Text??"").Length/62+1);int bubbleHeight=Math.Max(72,58+textLines*18+(string.IsNullOrWhiteSpace(m.ReplyToMessageId)?0:22));var row=new Panel{Width=Math.Max(500,history.ClientSize.Width-70),Height=bubbleHeight+8,BackColor=ThemeColors.Background};var b=new ModernPanel{Width=Math.Min(520,row.Width-80),Height=bubbleHeight,Left=mine?row.Width-Math.Min(520,row.Width-80)-8:8,Top=2,BackColor=mine?Color.FromArgb(222,239,255):ThemeColors.Surface,BorderRadius=18,BorderColor=ThemeColors.BorderColor,BorderSize=1};b.Controls.Add(new Label{Text=(mine?"You":(u==null?"Member":u.FullName))+(string.IsNullOrWhiteSpace(m.ReplyToMessageId)?"":"  ·  ↩ reply"),Location=new Point(12,7),AutoSize=true,ForeColor=ThemeColors.Primary,Font=new Font("Segoe UI Semibold",8,FontStyle.Bold)});b.Controls.Add(new Label{Text=m.Text+(string.IsNullOrWhiteSpace(m.Reaction)?"":"   "+m.Reaction),Location=new Point(12,28),Size=new Size(b.Width-24,Math.Max(24,textLines*18)),ForeColor=ThemeColors.TextPrimary,AutoEllipsis=true});b.Controls.Add(new Label{Text=m.CreatedAt.ToString("HH:mm"),Location=new Point(12,b.Height-20),AutoSize=true,ForeColor=ThemeColors.TextMuted,Font=new Font("Segoe UI",7.5F)});var menu=new ContextMenuStrip();menu.Items.Add("Reply").Click+=(s,e)=>{replyId=m.Id;replyPreview.Text="↩ Replying to: "+(m.Text.Length>55?m.Text.Substring(0,55)+"…":m.Text);replyPreview.Visible=true;input.Focus();};var react=new ToolStripMenuItem("Reaction");menu.Items.Add(react);foreach(var emoji in new[]{"👍","❤️","😂","🔥"}){var it=react.DropDownItems.Add(emoji);it.Click+=(s,e)=>{m.Reaction=((ToolStripItem)s).Text;db.Save();Render();};}if(mine||group.OwnerUserId==Session.CurrentUser.Id){menu.Items.Add("Delete").Click+=(s,e)=>{db.Data.GroupMessages.Remove(m);db.Save();Render();};}b.ContextMenuStrip=menu;row.Controls.Add(b);history.Controls.Add(row);} }
  async void Send(){if(string.IsNullOrWhiteSpace(input.Text))return;var text=input.Text.Trim();var id=Guid.NewGuid().ToString();db.Data.GroupMessages.Add(new GroupChatMessage{Id=id,GroupId=group.Id,FromUserId=Session.CurrentUser.Id,Text=text,CreatedAt=DateTime.Now,ReplyToMessageId=replyId});input.Clear();replyId=null;replyPreview.Visible=false;db.Save();try{if(realtime.State==RealtimeConnectionState.Connected)await realtime.SendGroupMessageAsync(id,group.Id,Session.CurrentUser.Id,text);}catch(Exception ex){AppLogger.Error("Realtime group send failed.",ex);}Render();}
  void ShowEmoji(Control anchor){var menu=new ContextMenuStrip();foreach(var e in new[]{"😀","😂","😍","👍","❤️","🔥","🎉","👏","🙏","😎"}){var it=menu.Items.Add(e);it.Click+=(s,a)=>{input.Text+=((ToolStripItem)s).Text;input.SelectionStart=input.Text.Length;input.Focus();};}menu.Show(anchor,new Point(0,-menu.PreferredSize.Height));}
  void Attach(){using(var d=new OpenFileDialog{Filter="Files|*.jpg;*.jpeg;*.png;*.gif;*.pdf;*.txt;*.doc;*.docx|All files|*.*"})if(d.ShowDialog(this)==DialogResult.OK){db.Data.GroupMessages.Add(new GroupChatMessage{Id=Guid.NewGuid().ToString(),GroupId=group.Id,FromUserId=Session.CurrentUser.Id,Text="📎 "+Path.GetFileName(d.FileName),AttachmentPath=d.FileName,CreatedAt=DateTime.Now});db.Save();Render();}}
  void AddMember(){if(group.OwnerUserId!=Session.CurrentUser.Id&&!group.AdminUserIds.Contains(Session.CurrentUser.Id)){MessageBox.Show("Only the owner or an admin can add members.");return;}var candidates=db.Data.Users.Where(x=>!group.MemberUserIds.Contains(x.Id)).OrderBy(x=>x.FullName).ToList();if(candidates.Count==0){MessageBox.Show("Everyone is already in this group.");return;}using(var picker=new Form{Text="Add members",StartPosition=FormStartPosition.CenterParent,Size=new Size(420,500),BackColor=ThemeColors.Background}){var list=new CheckedListBox{Dock=DockStyle.Fill,CheckOnClick=true,BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI",10)};foreach(var u in candidates)list.Items.Add(u.FullName+"  @"+u.Username);var ok=ButtonX("Add selected",230,410,140);ok.Anchor=AnchorStyles.Bottom|AnchorStyles.Right;ok.Click+=(s,e)=>picker.DialogResult=DialogResult.OK;picker.Controls.Add(list);picker.Controls.Add(ok);ok.BringToFront();if(picker.ShowDialog(this)==DialogResult.OK){for(int i=0;i<list.Items.Count;i++)if(list.GetItemChecked(i))group.MemberUserIds.Add(candidates[i].Id);db.Save();title.Text=group.Name;Render();}}}
  void SearchMessages(){string q=null;using(var f=new Form{Text="Search group messages",StartPosition=FormStartPosition.CenterParent,Size=new Size(430,180),BackColor=ThemeColors.Background,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var tb=new TextBox{Location=new Point(24,28),Size=new Size(365,34),Font=new Font("Segoe UI",10),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};f.Controls.Add(tb);var find=ButtonX("Find",279,82,110);find.Click+=(s,e)=>{q=tb.Text;f.DialogResult=DialogResult.OK;};f.Controls.Add(find);f.AcceptButton=find;f.ShowDialog(this);}if(string.IsNullOrWhiteSpace(q))return;var matches=db.Data.GroupMessages.Where(x=>x.GroupId==group.Id&&!string.IsNullOrWhiteSpace(x.Text)&&x.Text.IndexOf(q,StringComparison.OrdinalIgnoreCase)>=0).ToList();MessageBox.Show(matches.Count+" matching message(s).","Search");}
  void ShowSharedFiles(){var files=db.Data.GroupMessages.Where(x=>x.GroupId==group.Id&&!string.IsNullOrWhiteSpace(x.AttachmentPath)).OrderByDescending(x=>x.CreatedAt).ToList();if(files.Count==0){MessageBox.Show("No shared files yet.","Shared files");return;}MessageBox.Show(string.Join("\r\n",files.Take(20).Select(x=>Path.GetFileName(x.AttachmentPath)+"  ·  "+x.CreatedAt.ToString("MMM d, HH:mm"))),"Shared files");}
  void EditGroupProfile(){if(group.OwnerUserId!=Session.CurrentUser.Id&&!group.AdminUserIds.Contains(Session.CurrentUser.Id))return;using(var f=new Form{Text="Group profile",StartPosition=FormStartPosition.CenterParent,Size=new Size(470,330),BackColor=ThemeColors.Background}){var desc=new TextBox{Text=group.Description??"",Location=new Point(28,55),Size=new Size(395,90),Multiline=true,Font=new Font("Segoe UI",10),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};f.Controls.Add(new Label{Text="Description",Location=new Point(28,28),AutoSize=true,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI Semibold",9,FontStyle.Bold)});f.Controls.Add(desc);var avatar=ButtonX("Choose avatar",28,170,130);avatar.Click+=(s,e)=>{using(var d=new OpenFileDialog{Filter="Images|*.jpg;*.jpeg;*.png;*.bmp"})if(d.ShowDialog(f)==DialogResult.OK)group.AvatarPath=d.FileName;};f.Controls.Add(avatar);var save=ButtonX("Save profile",293,230,130);save.Click+=(s,e)=>{group.Description=desc.Text.Trim();db.Save();f.DialogResult=DialogResult.OK;};f.Controls.Add(save);f.ShowDialog(this);}}
  void ManageGroup(){if(group.OwnerUserId!=Session.CurrentUser.Id&&!group.AdminUserIds.Contains(Session.CurrentUser.Id)){if(MessageBox.Show("Leave this group?","Group",MessageBoxButtons.YesNo)==DialogResult.Yes){group.MemberUserIds.Remove(Session.CurrentUser.Id);group.AdminUserIds.Remove(Session.CurrentUser.Id);db.Save();Close();}return;}using(var f=new Form{Text="Manage group",StartPosition=FormStartPosition.CenterParent,Size=new Size(460,610),BackColor=ThemeColors.Background}){var rename=ButtonX("Rename group",24,24,130);rename.Click+=(s,e)=>{string n=null;using(var rf=new Form{Text="Rename group",StartPosition=FormStartPosition.CenterParent,Size=new Size(430,180),BackColor=ThemeColors.Background,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var tb=new TextBox{Text=group.Name,Location=new Point(24,28),Size=new Size(365,34),Font=new Font("Segoe UI",10),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary};rf.Controls.Add(tb);var save=ButtonX("Save",279,82,110);save.Click+=(ss,ee)=>{n=tb.Text;rf.DialogResult=DialogResult.OK;};rf.Controls.Add(save);rf.AcceptButton=save;if(rf.ShowDialog(f)!=DialogResult.OK)n=null;}if(!string.IsNullOrWhiteSpace(n)){group.Name=n.Trim();db.Save();title.Text=group.Name;f.Text="Manage "+group.Name;}};f.Controls.Add(rename);var profile=ButtonX("Group profile",164,24,130);profile.Click+=(s,e)=>EditGroupProfile();f.Controls.Add(profile);var list=new ListBox{Location=new Point(24,84),Size=new Size(390,300),BackColor=ThemeColors.Surface,ForeColor=ThemeColors.TextPrimary,Font=new Font("Segoe UI",10)};var members=group.MemberUserIds.Select(id=>db.Data.Users.FirstOrDefault(x=>x.Id==id)).Where(x=>x!=null).ToList();foreach(var u in members)list.Items.Add((group.OwnerUserId==u.Id?"★ Owner  ":group.AdminUserIds.Contains(u.Id)?"◆ Admin  ":"  ")+u.FullName+"  @"+u.Username);f.Controls.Add(list);var admin=ButtonX("Toggle admin",24,404,120);admin.Click+=(s,e)=>{if(list.SelectedIndex<0)return;var u=members[list.SelectedIndex];if(u.Id==group.OwnerUserId)return;if(group.AdminUserIds.Contains(u.Id))group.AdminUserIds.Remove(u.Id);else group.AdminUserIds.Add(u.Id);db.Save();f.Close();ManageGroup();};f.Controls.Add(admin);var transfer=ButtonX("Transfer owner",24,454,130);transfer.Visible=Session.CurrentUser.Id==group.OwnerUserId;transfer.Click+=(s,e)=>{if(list.SelectedIndex<0){MessageBox.Show("Select a member first.");return;}var u=members[list.SelectedIndex];if(u.Id==group.OwnerUserId)return;if(MessageBox.Show("Transfer ownership to "+u.FullName+"?","Transfer ownership",MessageBoxButtons.YesNo)==DialogResult.Yes){group.OwnerUserId=u.Id;if(!group.AdminUserIds.Contains(u.Id))group.AdminUserIds.Add(u.Id);group.AdminUserIds.Remove(Session.CurrentUser.Id);db.Save();f.Close();ManageGroup();}};f.Controls.Add(transfer);var remove=ButtonX("Remove",154,404,100);remove.BackColor=ThemeColors.AlertRed;remove.Click+=(s,e)=>{if(list.SelectedIndex<0)return;var u=members[list.SelectedIndex];if(u.Id==group.OwnerUserId)return;group.MemberUserIds.Remove(u.Id);group.AdminUserIds.Remove(u.Id);db.Save();f.Close();ManageGroup();};f.Controls.Add(remove);var leave=ButtonX("Leave group",264,404,120);leave.BackColor=ThemeColors.SurfaceHover;leave.ForeColor=ThemeColors.AlertRed;leave.Click+=(s,e)=>{if(Session.CurrentUser.Id==group.OwnerUserId){MessageBox.Show("Transfer ownership before leaving.");return;}group.MemberUserIds.Remove(Session.CurrentUser.Id);group.AdminUserIds.Remove(Session.CurrentUser.Id);db.Save();f.Close();Close();};f.Controls.Add(leave);var deleteGroup=ButtonX("Delete group",264,454,120);deleteGroup.Visible=Session.CurrentUser.Id==group.OwnerUserId;deleteGroup.BackColor=ThemeColors.AlertRed;deleteGroup.Click+=(s,e)=>{if(MessageBox.Show("Delete this group and all of its messages?","Delete group",MessageBoxButtons.YesNo)==DialogResult.Yes){db.Data.GroupMessages.RemoveAll(x=>x.GroupId==group.Id);db.Data.ChatGroups.Remove(group);db.Save();f.Close();Close();}};f.Controls.Add(deleteGroup);f.ShowDialog(this);}}
  void ShowInfo(){var names=group.MemberUserIds.Select(id=>db.Data.Users.FirstOrDefault(x=>x.Id==id)).Where(x=>x!=null).Select(x=>x.FullName).ToArray();var shared=db.Data.GroupMessages.Count(x=>x.GroupId==group.Id&&!string.IsNullOrWhiteSpace(x.AttachmentPath));if(MessageBox.Show(group.Name+"\r\n"+(string.IsNullOrWhiteSpace(group.Description)?"":group.Description+"\r\n")+"\r\nMembers: "+group.MemberUserIds.Count+"\r\nShared files: "+shared+"\r\nOwner: "+(db.Data.Users.FirstOrDefault(x=>x.Id==group.OwnerUserId)?.FullName??"Unknown")+"\r\n\r\n"+string.Join("\r\n",names)+"\r\n\r\nOpen shared files?","Group info",MessageBoxButtons.YesNo)==DialogResult.Yes)ShowSharedFiles();}
